      "inputs": {
        "script": "return { items: [{ amount: 50 }, { amount: 100 }, { amount: 150 }, { amount: 200 }, { amount: 75 }] };"
      },
      "outputs": {
        "output": {
          "type": "any",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
